define(["jquery","core/ajax","core/str"],function($,Ajax,Str){class VideoContent{constructor(root,config,player){this.root=root;this.config=config||{};this.player=player;this.points=Array.isArray(this.config.points)?this.config.points:[];this.triggered=new Set;this.active=null;this.playing=false;this.previousTime=Number(player.getCurrentTime()||0)}initialise(){if(!this.points.length){return this}this.player.onPlay(()=>{this.playing=true;if(this.active&&this.active.item.pause){this.player.pause()}});this.player.onPause(()=>this.playing=false);this.player.onEnded(()=>this.playing=false);this.player.onTimeUpdate(current=>this.update(Number(current)));this.player.onSeek(current=>this.update(Number(current)));this.root.querySelectorAll("[data-content-point]").forEach(element=>{element.addEventListener("click",()=>this.player.seek(Number(element.dataset.time||0)))});this.update(this.previousTime);return this}update(current){if(!Number.isFinite(current)){return}this.updateSidebar(current);if(!this.active){const due=this.findDueItem(current,this.previousTime);if(due){this.open(due.point,due.item)}}this.previousTime=current}findDueItem(current,previous){for(const point of this.points){if(Number(point.time)>current+.5){continue}for(const item of point.items||[]){if(item.required&&!item.completed&&!this.triggered.has(Number(item.id))){return{point:point,item:item}}}}if(current<previous){return null}for(const point of this.points){if(Number(point.time)<=previous+.25||Number(point.time)>current+.5){continue}const item=(point.items||[]).find(candidate=>!candidate.completed&&!this.triggered.has(Number(candidate.id)));if(item){return{point:point,item:item}}}return null}open(point,item,resumeOverride){const element=this.root.querySelector('[data-content-item="'+Number(item.id)+'"]');if(!element){this.triggered.add(Number(item.id));return}const resume=Boolean(resumeOverride||item.pause&&this.playing);this.active={point:point,item:item,element:element,resume:resume};element.hidden=false;if(item.pause){this.player.pause()}require([item.module],plugin=>plugin.open(element,this.api(),item))}api(){return{complete:response=>this.complete(response),dismiss:completed=>this.dismiss(Boolean(completed))}}complete(response){const active=this.active;if(!active){return Promise.reject(new Error("No active video content item"))}return Ajax.call([{methodname:"mod_videoprogress_complete_point",args:{cmid:Number(this.config.cmid),itemid:Number(active.item.id),response:JSON.stringify(response||{})}}])[0].then(result=>{const feedback=active.element.querySelector('[data-region="interaction-feedback"]');if(feedback){feedback.textContent=result.feedback||"";feedback.className="videoprogress-content-overlay__feedback "+(result.completed?"is-correct":"is-incorrect")}if(result.completed){active.item.completed=true}return result}).catch(error=>{return Str.get_string("interactionerror","videoprogress").then(message=>{const feedback=active.element.querySelector('[data-region="interaction-feedback"]');if(feedback){feedback.textContent=message;feedback.className="videoprogress-content-overlay__feedback is-incorrect"}throw error})})}dismiss(completed){if(!this.active){return}const previous=this.active;previous.element.hidden=true;this.triggered.add(Number(previous.item.id));if(completed){previous.item.completed=true}this.active=null;this.updateSidebar(this.player.getCurrentTime());const next=(previous.point.items||[]).find(item=>!item.completed&&!this.triggered.has(Number(item.id)));if(next){this.open(previous.point,next,previous.resume)}else if(previous.resume){this.player.play()}}updateSidebar(current){let activePoint=null;this.points.forEach(point=>{if(Number(point.time)<=current+.25){activePoint=point}});this.root.querySelectorAll("[data-content-point]").forEach(element=>{const active=activePoint&&Number(element.dataset.contentPoint)===Number(activePoint.id);element.classList.toggle("is-current",Boolean(active));if(active){element.setAttribute("aria-current","step")}else{element.removeAttribute("aria-current")}})}}const initialise=(root,config,player)=>new VideoContent(root,config,player).initialise();return{initialise:initialise}});